/**
 * Bookmark data access and validation.
 *
 * Scope note: this file grows across user stories. For the MVP (User Story 1)
 * it implements create / getById / list (newest-first) plus URL validation and
 * duplicate detection. Notes are stored (column exists); tags and edit/delete
 * arrive in later stories. The response shape already includes `tags` (empty
 * for now) so the API contract stays stable.
 */

/** True if `value` is a well-formed http/https URL. */
export function isValidHttpUrl(value) {
  if (typeof value !== "string" || value.trim() === "") return false;
  let parsed;
  try {
    parsed = new URL(value.trim());
  } catch {
    return false;
  }
  return parsed.protocol === "http:" || parsed.protocol === "https:";
}

/**
 * Conservative normalized form used only for duplicate detection.
 * Lowercases scheme + host and trims a single trailing slash from the path;
 * query and fragment are preserved so genuinely different pages stay distinct.
 */
export function normalizeUrlKey(value) {
  const parsed = new URL(value.trim());
  const scheme = parsed.protocol.toLowerCase();
  const host = parsed.host.toLowerCase();
  let path = parsed.pathname;
  if (path.length > 1 && path.endsWith("/")) path = path.slice(0, -1);
  return `${scheme}//${host}${path}${parsed.search}`;
}

function rowToBookmark(row) {
  if (!row) return null;
  return {
    id: row.id,
    url: row.url,
    title: row.title,
    note: row.note || "",
    tags: [], // populated in User Story 3
    created_at: row.created_at,
  };
}

export function createBookmarkModel(db) {
  const insertStmt = db.prepare(
    `INSERT INTO bookmarks (url, title, note, url_key, created_at)
     VALUES (@url, @title, @note, @url_key, @created_at)`
  );
  const getByIdStmt = db.prepare(`SELECT * FROM bookmarks WHERE id = ?`);
  const findByKeyStmt = db.prepare(`SELECT * FROM bookmarks WHERE url_key = ? LIMIT 1`);
  const listNewestStmt = db.prepare(`SELECT * FROM bookmarks ORDER BY created_at DESC, id DESC`);

  return {
    /** Look up an existing bookmark by normalized url, or null. */
    findByUrl(url) {
      return rowToBookmark(findByKeyStmt.get(normalizeUrlKey(url)));
    },

    /**
     * Create a bookmark. Caller is responsible for having resolved the title
     * (auto-fetch happens in the API layer). Assumes `url` is already validated.
     */
    create({ url, title, note = "", createdAt }) {
      const cleanUrl = url.trim();
      const finalTitle = title && title.trim() ? title.trim() : cleanUrl;
      const info = insertStmt.run({
        url: cleanUrl,
        title: finalTitle,
        note: note || "",
        url_key: normalizeUrlKey(cleanUrl),
        created_at: createdAt || new Date().toISOString(),
      });
      return rowToBookmark(getByIdStmt.get(info.lastInsertRowid));
    },

    getById(id) {
      return rowToBookmark(getByIdStmt.get(id));
    },

    /** List bookmarks, newest first. */
    list() {
      return listNewestStmt.all().map(rowToBookmark);
    },
  };
}

