:root {
  --fg: #1a1a1a;
  --muted: #666;
  --border: #e0e0e0;
  --accent: #2b6cb0;
  --bg: #f7f7f8;
}

* {
  box-sizing: border-box;
}

body {
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color: var(--fg);
  background: var(--bg);
  margin: 0;
  padding: 0;
}

header {
  padding: 1.25rem 1.5rem;
  border-bottom: 1px solid var(--border);
  background: #fff;
}

header h1 {
  margin: 0;
  font-size: 1.4rem;
}

main {
  max-width: 760px;
  margin: 0 auto;
  padding: 1.5rem;
}

#add-form {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-bottom: 1rem;
}

#add-form input {
  flex: 1 1 220px;
  padding: 0.6rem 0.7rem;
  border: 1px solid var(--border);
  border-radius: 6px;
  font-size: 0.95rem;
}

#add-form button {
  padding: 0.6rem 1.1rem;
  border: none;
  border-radius: 6px;
  background: var(--accent);
  color: #fff;
  font-size: 0.95rem;
  cursor: pointer;
}

#add-form button:hover {
  background: #245a94;
}

.message {
  margin: 0 0 1rem;
  padding: 0.6rem 0.8rem;
  border-radius: 6px;
  font-size: 0.9rem;
}

.message.error {
  background: #fdecea;
  color: #8a1c14;
}

.message.warn {
  background: #fff6e5;
  color: #7a5300;
}

.message.success {
  background: #e8f5e9;
  color: #1b5e20;
}

#bookmark-list {
