/**
 * Bookmark data access and validation.
 *
 * Scope note: this file grows across user stories. For the MVP (User Story 1)
 * it implements create / getById / list (newest-first) plus URL validation and
 * duplicate detection. Notes are stored (column exists); tags and edit/delete
 * arrive in later stories. The response shape already includes `tags` (empty
 * for now) so the API contract stays stable.
 */

/** True if `value` is a well-formed http/https URL. */
export function isValidHttpUrl(value) {
  if (typeof value !== "string" || value.trim() === "") return false;
  let parsed;
  try {
    parsed = new URL(value.trim());
  } catch {
    return false;
  }
  return parsed.protocol === "http:" || parsed.protocol === "https:";
}

/**
