  // DELETE /api/bookmarks/:id (FR-012; UI enforces the confirmation step)
  router.delete("/bookmarks/:id", (req, res) => {
    const removed = model.delete(Number(req.params.id));
    if (!removed) return res.status(404).json({ error: "not_found" });
    res.status(204).end();
  });

  return router;
}

